def recipe_totals(items: list[tuple[str, float]], foods: dict[str, dict]) -> dict[str, float]:
    """kcal and protein of a recipe from the catalog values per 100 g."""
    kcal = sum(foods[n]["kcal"] * g / 100 for n, g in items)
    protein = sum(foods[n]["protein"] * g / 100 for n, g in items)
    return {"kcal": round(kcal), "protein": round(protein, 1)}


def add_recipes(db: sqlite3.Connection) -> int:
    """Insert the recipes whose name is not in ``templates`` yet; returns how many were added."""
    have = {row[0].strip().lower() for row in db.execute("SELECT name FROM templates")}
    added = 0
    for name, category, steps, items in RECIPES:
        if name.lower() in have:
            continue
        payload = {"items": [{"food": food, "grams": grams} for food, grams in items], "category": category, "recipe": True}
        db.execute(
            "INSERT INTO templates(name, notes, kind, payload) VALUES(?, ?, 'meal', ?)",
            (name, steps, json.dumps(payload, ensure_ascii=False)),
        )
        added += 1
    return added
